import{_ as t,o as a,c as o,a5 as s}from"./chunks/framework.Bj-lFevX.js";const g=JSON.parse('{"title":"What is Swagger-PHP?","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),i={name:"guide/index.md"};function r(n,e,c,d,p,l){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="what-is-swagger-php" tabindex="-1">What is Swagger-PHP? <a class="header-anchor" href="#what-is-swagger-php" aria-label="Permalink to &quot;What is Swagger-PHP?&quot;">​</a></h1><p><code>swagger-php</code> is a library that extracts API metadata from your PHP source code files.</p><p>The idea is to add <code>swagger-php</code> <a href="./using-attributes.html">attributes</a> next to the relevant PHP code in your application. These will contain the details about your API and <code>swagger-php</code> will convert those into machine-readable <a href="https://spec.openapis.org/oas/v3.1.0.html" target="_blank" rel="noreferrer">OpenAPI documentation</a>.</p><p>Keeping your API documentation next to the corresponding source code (same file!) makes it easy to keep up-to-date, as all details can be modified in one place.</p><div class="tip custom-block"><p class="custom-block-title">Annotating</p><p>Annotating your code means adding metadata to the source code for <code>swagger-php</code>. This is done with <a href="./using-attributes.html">attributes</a>, classic attributes or <a href="./using-annotations.html">docblock annotations</a>.</p></div><div class="warning custom-block"><p class="custom-block-title">Requirements</p><p>Using <code>swagger-php</code> requires a minimum of <strong>PHP 8.2</strong>.</p></div>',6)])])}const u=t(i,[["render",r]]);export{g as __pageData,u as default};
